<script setup>
import{onMounted,ref}from'vue';import{selfEvaluationApi as api}from'../../selfEvaluationApi'
const tasks=ref([]),task=ref(null),form=ref(null),entry=ref(null),materials=ref([]),file=ref(null),message=ref(''),messageType=ref('success')
function notice(text,type='success'){message.value=text;messageType.value=type}
async function load(){try{tasks.value=await api.tasks()}catch(e){notice(e.message,'error')}}
async function selectTask(id){form.value=null;entry.value=null;materials.value=[];if(!id){task.value=null;return}try{task.value=await api.task(id)}catch(e){notice(e.message,'error')}}
async function selectForm(id){entry.value=null;materials.value=[];if(!id){form.value=null;return}try{form.value=await api.form(id)}catch(e){notice(e.message,'error')}}
async function selectEntry(x){entry.value=x;try{materials.value=await api.materials(x.id)}catch(e){notice(e.message,'error')}}
async function upload(replace=null){if(!file.value||!entry.value)return;try{await api.upload(entry.value.id,{materialName:file.value.name,category:null,description:'自评佐证材料',versionGroup:replace?.version_group||null,confirmClassification:false},file.value);materials.value=await api.materials(entry.value.id);message.value=replace?'材料新版本已上传，历史版本保留':'材料已上传，请确认分类';file.value=null}catch(e){message.value=e.message}}
async function replaceFile(x,event){const replacement=event.target.files?.[0];event.target.value='';if(!replacement||!entry.value)return;try{await api.upload(entry.value.id,{materialName:replacement.name,category:null,description:'自评佐证材料替换版本',versionGroup:x.version_group,confirmClassification:false},replacement);materials.value=await api.materials(entry.value.id);notice('材料新版本已上传，历史版本已保留')}catch(e){notice(e.message,'error')}}
async function classify(x){const category=prompt('材料分类',x.category);if(!category)return;try{await api.classify(x.id,category);materials.value=await api.materials(entry.value.id);notice('材料分类已人工确认')}catch(e){notice(e.message,'error')}}
async function disable(x){if(!confirm('确认逻辑停用当前材料？历史记录和文件仍会保留。'))return;try{await api.disable(x.id);materials.value=await api.materials(entry.value.id);notice('材料已逻辑停用')}catch(e){notice(e.message,'error')}}
function canPreview(x){return x.content_type==='application/pdf'||String(x.content_type||'').startsWith('image/')}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-info">按任务、机构和指标管理佐证材料；文件名和指标编码只提供简单分类建议，必须人工确认，不使用OCR。</div><div v-if="message" class="alert" :class="messageType==='error'?'alert-danger':'alert-success'">{{message}}</div>
<div class="card task-selector-card"><div class="selector-grid"><div class="form-item task-select-item"><label>自评任务</label><p class="field-help">选择需要维护佐证材料的部门自评任务</p><select class="task-select" @change="selectTask($event.target.value)"><option value="">请选择自评任务</option><option v-for="x in tasks" :key="x.id" :value="x.id">{{x.task_name}}</option></select></div><div v-if="task" class="form-item task-select-item"><label>参评机构</label><p class="field-help">选择机构后，可继续按指标管理材料</p><select class="task-select" @change="selectForm($event.target.value)"><option value="">请选择参评机构</option><option v-for="x in task.organizations" :key="x.id" :value="x.id">{{x.unit_name}} / {{x.status}}</option></select></div></div></div>
<div v-if="!task" class="card empty-state"><div class="empty-icon">📂</div><h3>请先选择一个自评任务</h3><p>选择任务后，可按机构和指标上传、分类及管理佐证材料</p><div class="empty-steps"><span>选择任务</span><b>→</b><span>选择机构</span><b>→</b><span>管理指标材料</span></div></div>
<div v-if="form" class="card"><div class="card-header"><h3>📁 指标材料柜</h3><span>{{form.unit_name}}</span></div><div class="cabinet-grid"><div class="folder-list"><button v-for="x in form.entries" :key="x.id" class="folder-item" :class="{active:entry?.id===x.id}" @click="selectEntry(x)">{{x.indicator_code}} {{x.indicator_name}}（{{x.material_count}}）</button></div><div v-if="entry"><div v-if="['NOT_STARTED','DRAFT','RETURNED'].includes(form.status)" class="btn-group"><input type="file" @change="file=$event.target.files[0]"><button class="btn btn-primary" @click="upload()">上传材料</button></div><table><thead><tr><th>材料</th><th>版本</th><th>分类</th><th>来源</th><th>当前</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!materials.length"><td colspan="7">暂无材料</td></tr><tr v-for="x in materials" :key="x.id"><td>{{x.material_name}}</td><td>V{{x.version_no}}</td><td>{{x.category}} / {{x.classification_status}}</td><td>{{x.classification_source}}</td><td>{{x.is_current?'是':'历史'}}</td><td>{{x.status}}</td><td><a v-if="canPreview(x)" class="btn btn-sm btn-outline" :href="api.preview(x.attachment_id)" target="_blank" rel="noopener">预览</a> <a class="btn btn-sm btn-outline" :href="api.download(x.attachment_id)">下载</a> <button v-if="x.classification_status==='SUGGESTED'" class="btn btn-sm btn-primary" @click="classify(x)">确认分类</button> <label v-if="x.is_current&&x.status==='ACTIVE'&&['NOT_STARTED','DRAFT','RETURNED'].includes(form.status)" class="btn btn-sm btn-outline">替换<input type="file" hidden @change="replaceFile(x,$event)"></label> <button v-if="x.is_current&&x.status==='ACTIVE'&&['NOT_STARTED','DRAFT','RETURNED'].includes(form.status)" class="btn btn-sm btn-outline" @click="disable(x)">停用</button></td></tr></tbody></table></div></div></div>
</section></template>
<style scoped>
.task-selector-card{padding:22px 30px}.selector-grid{display:flex;align-items:flex-start;gap:28px;flex-wrap:wrap}.task-select-item{min-width:min(420px,100%)}.task-select-item label{display:block;margin-bottom:5px;font-weight:600;color:#1f2937}.field-help{margin:0 0 10px;color:#8a94a6;font-size:13px}.task-select{width:min(420px,100%);min-height:42px}.empty-state{min-height:310px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:48px 24px}.empty-icon{width:70px;height:70px;border-radius:20px;background:#eaf4ff;display:flex;align-items:center;justify-content:center;font-size:34px;margin-bottom:18px}.empty-state h3{margin:0 0 10px;color:#1f2937;font-size:20px}.empty-state>p{margin:0;color:#7b8798}.empty-steps{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:24px;color:#667085;font-size:13px}.empty-steps span{padding:8px 14px;border:1px solid #dbe5f0;border-radius:18px;background:#f8fafc}.empty-steps b{color:#9aa8ba;font-weight:400}.folder-item{display:block;width:100%;border:0;background:#f5f7fa;padding:12px;text-align:left;margin-bottom:6px}.folder-item.active{background:#e6f0ff;color:#1769d2}@media(max-width:640px){.task-selector-card{padding:18px}.task-select-item{width:100%}.task-select{width:100%}.empty-state{min-height:260px}.empty-steps{gap:7px}}
</style>
